observation.command:
cd /workspace && cat > /tmp/launch-app.mjs <<'EOF'
import { spawn } from 'node:child_process';
import { buildProfileEnv } from '/workspace/scripts/ops/runtime/profile-env.ts';

const env = buildProfileEnv('local-builder', { rootDir: '/workspace' });
env.NX_DAEMON = 'false';
env.NO_COLOR = '1';

const child = spawn('pnpm', ['nx', 'run', 'sva-studio-react:serve'], {
  cwd: '/workspace',
  env,
  stdio: 'ignore',
  detached: true,
});
child.unref();
console.log('launched dev server pid', child.pid);
EOF
nohup pnpm exec tsx /tmp/launch-app.mjs > /tmp/launch.log 2>&1 &
sleep 5; cat /tmp/launch.log; ps aux | grep -c '[s]va-studio-react:serve'
